require __DIR__.'/../../app/bootstrap.php';require_once __DIR__.'/../../app/api_v1.php';if(!setting_bool('mobile_api_enabled',true))api_json(['ok'=>false,'error'=>'Mobile API is disabled'],503);$in=api_input();$challenge=trim((string)($in['challenge']??''));$code=trim((string)($in['code']??''));if($challenge===''||$code==='')api_json(['ok'=>false,'error'=>'Challenge and code required'],422);$q=db()->prepare("SELECT c.*,u.name,u.role,u.email FROM mobile_api_challenges c JOIN users u ON u.id=c.user_id WHERE c.challenge_hash=? AND c.consumed_at IS NULL AND c.expires_at>NOW() LIMIT 1");$q->execute([hash('sha256',$challenge)]);$r=$q->fetch();if(!$r||!security_verify_otp((int)$r['user_id'],$code,'mobile_api'))api_json(['ok'=>false,'error'=>'Invalid or expired code'],401);db()->prepare('UPDATE mobile_api_challenges SET consumed_at=NOW() WHERE id=?')->execute([$r['id']]);$token=api_issue_token((int)$r['user_id'],(string)$r['device_name']);security_record_login(true,(string)$r['email'],(int)$r['user_id'],'mobile');api_json(['ok'=>true,'auth'=>$token,'user'=>['id'=>(int)$r['user_id'],'name'=>$r['name'],'role'=>$r['role']]]);